create table public.sigtap_procedures(id uuid primary key default gen_random_uuid(),code text not null unique,name text not null,complexity text,financing text,active boolean not null default true,competence text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.sus_production(id uuid primary key default gen_random_uuid(),municipality_id uuid not null references public.municipalities(id),request_id uuid references public.transport_requests(id),patient_id uuid not null references public.patients(id),health_unit_id uuid references public.health_units(id),professional_link_id uuid references public.health_professional_links(id),procedure_id uuid not null references public.sigtap_procedures(id),production_date date not null,quantity integer not null default 1 check(quantity>0),production_type text not null default 'BPA_I' check(production_type in ('BPA_C','BPA_I','TFD')),status text not null default 'DRAFT' check(status in ('DRAFT','VALIDATED','EXPORTED','CANCELLED')),notes text,created_by uuid references public.profiles(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
alter table public.sigtap_procedures enable row level security; alter table public.sus_production enable row level security;
create policy sigtap_read on public.sigtap_procedures for select to authenticated using(true);
create policy sigtap_admin on public.sigtap_procedures for all to authenticated using((select private.current_user_role())='ADMIN'::public.user_role) with check((select private.current_user_role())='ADMIN'::public.user_role);
create policy production_read on public.sus_production for select to authenticated using((select private.current_user_role())='ADMIN'::public.user_role or municipality_id=(select private.current_user_municipality_id()));
create policy production_manage on public.sus_production for all to authenticated using((select private.current_user_role())='ADMIN'::public.user_role or (municipality_id=(select private.current_user_municipality_id()) and (select private.current_user_role())=any(array['GESTOR'::public.user_role,'OPERADOR'::public.user_role]))) with check((select private.current_user_role())='ADMIN'::public.user_role or (municipality_id=(select private.current_user_municipality_id()) and (select private.current_user_role())=any(array['GESTOR'::public.user_role,'OPERADOR'::public.user_role])));
create index sus_production_municipality_date_idx on public.sus_production(municipality_id,production_date desc);create index sus_production_request_idx on public.sus_production(request_id);create index sigtap_procedures_code_idx on public.sigtap_procedures(code);